package com.bank.portal.controller;

import com.bank.portal.service.AuthService;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpSession;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/api/v1/auth")
public class LoginController {

    private static final Logger log = LoggerFactory.getLogger(LoginController.class);
    private final AuthService authService;

    public LoginController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public String login(@RequestParam String username,
                        @RequestParam String password,
                        HttpServletRequest request) {
        if (!authService.verify(username, password)) {
            return "LOGIN_FAILED";
        }
        // Regenerate the session id on login to prevent session fixation:
        // invalidate any pre-existing session, then create a fresh one.
        HttpSession old = request.getSession(false);
        if (old != null) old.invalidate();
        HttpSession session = request.getSession(true);

        // Sensitive state lives ON THE SERVER, not in a cookie.
        session.setAttribute("userId", username);
        session.setAttribute("roles", List.of("CUSTOMER"));
        log.info("Login success for {}, new session {}", username, session.getId());
        return "LOGIN_OK";
    }
}
