package com.bank.portal.controller;

import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;
import jakarta.servlet.http.Cookie;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;

@RestController
@RequestMapping("/api/v1/bills")
public class BillPaymentController {

    private static final Logger log = LoggerFactory.getLogger(BillPaymentController.class);

    // Step 1: choose biller — stored in the server session, not sent to client.
    @PostMapping("/step1")
    public String chooseBiller(@RequestParam String biller, HttpSession session) {
        session.setAttribute("biller", biller);
        return "BILLER_SET";
    }

    // Step 2: enter amount — accumulates in the same server session.
    @PostMapping("/step2")
    public String enterAmount(@RequestParam BigDecimal amount, HttpSession session) {
        session.setAttribute("amount", amount);
        return "AMOUNT_SET";
    }

    // Step 3: confirm — reads the accumulated workflow state from the session.
    @PostMapping("/confirm")
    public String confirm(HttpSession session) {
        String userId = (String) session.getAttribute("userId");
        String biller = (String) session.getAttribute("biller");
        BigDecimal amount = (BigDecimal) session.getAttribute("amount");
        if (userId == null) return "NOT_LOGGED_IN";
        log.info("Bill payment: {} pays {} to {}", userId, amount, biller);
        return "PAID " + amount + " to " + biller;
    }

    // A small, non-sensitive preference legitimately stored in a cookie.
    @PostMapping("/language")
    public String setLanguage(@RequestParam String lang, HttpServletResponse response) {
        Cookie cookie = new Cookie("lang", lang);
        cookie.setHttpOnly(false);  // UI may read it; it is not sensitive
        cookie.setPath("/");
        cookie.setMaxAge(60 * 60 * 24 * 30);
        response.addCookie(cookie);
        return "LANG_SET=" + lang;
    }
}
